      <nav class="nav-main">
        <a href="menu.html">Menu</a>
        <a href="rewards.html">Rewards</a>
        <a href="gift.html">Gift Cards</a>
        <a href="store-locator.html">Find a store</a>
      </nav>
      <div class="nav-actions">
        <button class="btn btn-outline">Sign in</button>
        <button class="btn btn-primary">Join now</button>
      </div>
    </div>
  </header>

  <!-- Cookie Banner -->
  <div class="cookie-banner" id="cookieBanner">
    <p>This site uses cookies, but not the kind you eat. We use cookies to remember log in details, provide secure log in, improve site functionality, and deliver personalized content.</p>
    <div class="cookie-actions">
      <button onclick="hideCookieBanner()">Change cookie settings</button>
      <button class="btn-cookie-agree" onclick="agreeCookieBanner()">Agree</button>
    </div>
  </div>

  <!-- Hero -->
  <section class="hero">
    <div class="container hero-content">
      <div class="hero-text">
        <h1>It's a great day for coffee</h1>
        <p>Start your day with handcrafted beverages, fresh pastries, and the warmth of a community that feels like home.</p>
        <button class="btn btn-primary">Start an order</button>
      </div>
      <div class="hero-image">
        <div class="hero-image-placeholder">[Coffee lifestyle imagery]<br>hands wrapped around mug</div>
      </div>
    </div>
  </section>

  <!-- Featured Product -->
  <section class="featured-product">
    <div class="container">
      <div class="featured-card">
        <div class="featured-card-content">
          <h2>New Citrus Energy Refreshers just dropped</h2>
          <p>Introducing a new kind of energy. Now you can enjoy the Refreshers you love with extra caffeine from nature and a B-vitamin boost.</p>
          <button class="btn">Give them a try</button>
        </div>
        <div class="featured-card-image">[Citrus Energy Refreshers image]</div>
      </div>
    </div>
  </section>

  <!-- Afternoon Promo -->
  <section class="afternoon-promo">
    <div class="container">
      <div class="promo-grid">
        <div class="promo-card">
          <h3>Your afternoon reset</h3>
          <p>When 2 p.m. hits and you need a little boost, we've got you covered — with tasty drinks, snacks and sweet treats to keep the good vibes going.</p>
          <a href="menu.html" class="btn btn-outline">Explore our afternoon menu</a>
        </div>
        <div class="promo-card">
          <h3>Order ahead</h3>
          <p>Skip the line and pick up your order on your schedule. Your perfect coffee awaits, ready when you are.</p>
          <button class="btn btn-primary">Order now</button>
        </div>
        <div class="promo-card">
          <h3>Drive-thru pickup</h3>
          <p>Quick, convenient, and freshly made. Pull up to our drive-thru and grab your order without leaving your car.</p>
          <button class="btn btn-outline">Find a store</button>
        </div>
      </div>
    </div>
  </section>

  <!-- AI Recommendation -->
  <section class="featured-product">
    <div class="container">
      <div class="ai-recommendation">
        <h2>Inspire your next order with ChatGPT</h2>
        <p>Discover drinks that fit your mood, goals and preferences in just a few conversational prompts.</p>
        <button class="btn btn-primary">Learn more</button>
      </div>
    </div>
  </section>

  <!-- Seasonal Highlight 1 -->
  <section class="seasonal-section">
    <div class="container">
      <div class="section-header">
        <h2>Seasonal Highlights</h2>
      </div>
      <div class="seasonal-cards">
        <div class="seasonal-card fruity">
          <div class="seasonal-card-image">[Iced Mango Cream Matcha & Chai]</div>
          <div class="seasonal-card-content">
            <h3>A new fruity twist is here</h3>
            <p>Introducing vibrant Iced Mango Cream Matcha and rich Iced Mango Cream Chai. Topped with velvety mango cream cold foam for a delicious pop of sweetness, sip after sip.</p>
            <button class="btn btn-primary">Order now</button>
          </div>
        </div>
        <div class="seasonal-card spring">
          <div class="seasonal-card-image">[Lavender & Ube drinks]</div>
          <div class="seasonal-card-content">
            <h3>Spring starts now</h3>
            <p>Iced Lavender Cream Matcha and Iced Lavender Cream Chai are back in bloom, joined by the new Iced Ube Coconut Macchiato, Toasted Coconut Cream Cold Brew and so much more.</p>
            <button class="btn btn-primary">See the spring menu</button>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- Nondairy Promo -->
  <section class="nondairy-promo">
    <div class="container">
      <div class="nondairy-card">
        <div class="nondairy-content">
          <h2>Nondairy, No extra</h2>
          <p>Enjoy your beverage with your choice of nondairy milk — like oat, almond, coconut or soy — for no additional charge.</p>
          <button class="btn btn-primary">Start an order</button>
        </div>
        <div class="nondairy-image">[Nondairy milk options]</div>
      </div>
    </div>
  </section>

  <!-- Footer -->
